  <div><SectionLabel>{t("Published news")}</SectionLabel><div className="mt-3 space-y-3">{newsQuery.data?.map(item => <article key={item.id} className="rounded-xl border border-[#e6ebe6] bg-[#fbfdfb] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#8aa09d]">NEWS · {item.authorName || t("BusinessNotes member")}</p><h3 className="mt-2 text-base font-extrabold text-[#23475d]">{item.title || t("Untitled news")}</h3><p className="mt-2 whitespace-pre-wrap text-xs leading-5 text-[#66818a]">{item.body}</p>{item.sources?.length ? <div className="mt-3 border-t border-[#e8eee9] pt-3"><p className="text-[9px] font-extrabold uppercase tracking-[0.12em] text-[#8aa09d]">{t("Sources")}</p><div className="mt-1 space-y-1">{item.sources.map(source => <a key={source.id} href={source.url} target="_blank" rel="noreferrer" className="block text-[10px] font-bold text-[#39747b] underline">{source.publisher || source.title || source.url} · {source.verificationStatus}</a>)}</div></div> : null}<p className="mt-2 text-[10px] text-[#9aa7aa]">{item.publishedAt ? new Date(item.publishedAt).toLocaleString() : ""}</p></article>)}{!newsQuery.data?.length && <p className="rounded-xl bg-[#f8f9f5] p-4 text-xs text-[#819198]">{t("No published news yet")}</p>}</div></div>
