      {activePanel === "Companies" && <div className="mt-5 space-y-4"><div className="rounded-xl border border-[#e6ebe6] bg-[#fbfdfb] p-4"><p className="mb-3 text-xs font-extrabold text-[#23475d]">{editingCompanyId ? t("Edit company") : t("Create company")}</p><div className="grid gap-3 sm:grid-cols-2"><Input value={companyData.name} onChange={event => setCompanyData(previous => ({ ...previous, name: event.target.value }))} placeholder={t("Company name")} aria-label={t("Company name")} className="bg-white text-xs" /><Input value={companyData.industry} onChange={event => setCompanyData(previous => ({ ...previous, industry: event.target.value }))} placeholder={t("Industry")} aria-label={t("Industry")} className="bg-white text-xs" /><Input value={companyData.location} onChange={event => setCompanyData(previous => ({ ...previous, location: event.target.value }))} placeholder={t("City or market")} aria-label={t("City or market")} className="bg-white text-xs" /><Input value={companyData.website} onChange={event => setCompanyData(previous => ({ ...previous, website: event.target.value }))} placeholder={t("Website (optional)")} aria-label={t("Website (optional)")} className="bg-white text-xs" /></div><Textarea value={companyData.description} onChange={event => setCompanyData(previous => ({ ...previous, description: event.target.value }))} placeholder={t("Company description")} aria-label={t("Company description")} className="mt-3 min-h-20 bg-white text-xs shadow-none" /><div className="mt-3 flex gap-2"><Button onClick={() => { if (!isAuthenticated) return toast.info(t("Sign in to manage companies")); if (!companyData.name.trim() || !companyData.description.trim() || !companyData.industry.trim() || !companyData.location.trim()) return toast.error(t("Complete all required company fields")); if (editingCompanyId) updateCompanyMutation.mutate({ companyId: editingCompanyId, ...companyData }); else createCompanyMutation.mutate(companyData); }} disabled={createCompanyMutation.isPending || updateCompanyMutation.isPending} className="h-9 rounded-full bg-[#2b9a8b] px-4 text-xs font-bold">{editingCompanyId ? t("Save changes") : t("Create company")}</Button>{editingCompanyId && <Button variant="outline" onClick={() => { setEditingCompanyId(null); setCompanyData({ name: "", description: "", industry: "", location: "", website: "" }); }} className="h-9 rounded-full text-xs">{t("Cancel")}</Button>}</div></div>{companiesQuery.isLoading && <p className="text-xs text-[#66818a]">{t("Loading companies...")}</p>}{companiesQuery.data?.map(company => <div key={company.id} className="rounded-xl bg-[#f8f9f5] p-4 text-xs"><div className="flex items-start justify-between gap-3"><div><p className="font-extrabold text-[#23475d]">{company.name} {company.verified ? <span className="ml-1 inline-flex items-center gap-1 text-[#2b9a8b]"><CheckCircle2 size={12} />{t("Verified")}</span> : null}</p><p className="mt-1 text-[#66818a]">{company.industry} · {company.location}</p><p className="mt-1 text-[#819198]">{company.description}</p></div><div className="flex shrink-0 gap-2"><button onClick={() => { setEditingCompanyId(company.id); setCompanyData({ name: company.name, description: company.description ?? "", industry: company.industry ?? "", location: company.location ?? "", website: company.website ?? "" }); }} className="rounded-full bg-white p-2 text-[#66818a]" aria-label={t("Edit company")}><Pencil size={13} /></button>{!company.verified && <button onClick={() => requestVerificationMutation.mutate({ entityType: "company", entityId: company.id, note: "Company verification requested by owner." })} disabled={requestVerificationMutation.isPending} className="rounded-full bg-white px-3 py-1.5 text-[10px] font-bold text-[#2b796d]">{t("Request verification")}</button>}</div></div></div>)}</div>}
