        {newsQuery.data?.map(item => <article key={item.id} className="rounded-xl border border-[#e6ebe6] bg-white p-4"><div className="flex items-center gap-2"><Badge className="border-0 bg-[#eef4f2] text-[#53737b]">News</Badge>{item.verificationStatus === "verified" && <span className="flex items-center gap-1 text-[10px] font-bold text-[#2b9a8b]"><ShieldCheck size={12}/>Verified source</span>}</div><h3 className="mt-3 text-lg font-extrabold text-[#23475d]"><a href={`/news/${item.id}`} className="hover:underline">{item.title || "Untitled news"}</a></h3><p className="mt-2 whitespace-pre-wrap text-xs leading-6 text-[#5d737b]">{item.body}</p>{item.source && <a href={item.source} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-1 text-[10px] font-bold text-[#2a7181] hover:underline"><Link2 size={12}/> Source</a>}<button onClick={() => setSourcePreviewPostId(item.id)} className="ml-3 mt-3 text-[10px] font-bold text-[#315f70] underline-offset-2 hover:underline">View source records</button><p className="mt-3 text-[10px] text-[#9aa7aa]">Published {item.publishedAt ? new Date(item.publishedAt).toLocaleString() : "—"}</p></article>)}
        {sourcePreviewPostId !== null && <div className="rounded-xl border border-[#dfe9e4] bg-[#fbfdfb] p-4"><div className="flex items-center justify-between"><p className="text-xs font-extrabold text-[#315267]">Source records</p><button onClick={() => setSourcePreviewPostId(null)} className="text-[10px] font-bold text-[#819198]">Close</button></div>{sourcesPreviewQuery.data?.map(source => <div key={source.id} className="mt-2 rounded-lg bg-white p-3 text-[10px] text-[#66818a]"><p className="font-bold text-[#315267]">{source.title || source.publisher || source.url}</p><p className="mt-1 break-all">{source.url}</p><p className="mt-1">Status: {source.verificationStatus}</p></div>)}{!sourcesPreviewQuery.data?.length && <p className="mt-2 text-[11px] text-[#819198]">No additional source records.</p>}</div>}
{!newsQuery.data?.length && <p className="rounded-xl bg-[#f8f9f5] p-5 text-xs text-[#819198]">No published news yet.</p>}
