        <div className="space-y-2">{editorialQuery.data?.map(item => <div key={item.id} className="rounded-xl border border-[#e6ebe6] bg-white p-4"><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><Badge className="border-0 bg-[#eef4f2] text-[#53737b]">{item.type}</Badge><Badge className="border-0 bg-[#f5f5f1] text-[#667b82]">{item.status}</Badge></div><p className="mt-2 text-sm font-extrabold text-[#23475d]">{item.title || "Untitled"}</p><p className="mt-1 line-clamp-2 text-[11px] leading-5 text-[#819198]">{item.body}</p></div><span className="text-[10px] text-[#9aa7aa]">#{item.id}</span></div><div className="mt-3 flex flex-wrap gap-2">{item.status === "draft" || item.status === "rejected" ? <button onClick={() => submitEditorialMutation.mutate({ postId: item.id })} disabled={submitEditorialMutation.isPending} className="rounded-full bg-[#2b9a8b] px-3 py-1.5 text-[10px] font-bold text-white">Submit for review</button> : null}{["rejected", "takedown"].includes(item.status) ? <button onClick={() => { const reason = window.prompt("Appeal reason"); if (reason?.trim()) appealEditorialMutation.mutate({ postId: item.id, reason: reason.trim() }); }} className="rounded-full bg-[#fff5df] px-3 py-1.5 text-[10px] font-bold text-[#8b5b12]">Appeal</button> : null}{item.status === "published" && <button onClick={() => setCorrectionHistoryPostId(item.id)} className="rounded-full bg-[#eef4f2] px-3 py-1.5 text-[10px] font-bold text-[#53737b]">Correction history</button>}</div>{correctionHistoryPostId === item.id && <div className="mt-3 rounded-xl bg-[#f8f9f5] p-3">{correctionHistoryQuery.data?.length ? correctionHistoryQuery.data.map((c:any) => <div key={c.id} className="border-b border-[#e7ebe6] py-2 last:border-0"><p className="text-[10px] font-bold text-[#53737b]">{c.reason}</p><p className="mt-1 text-[10px] text-[#819198]">{new Date(c.createdAt).toLocaleString()}</p></div>) : <p className="text-[10px] text-[#819198]">No corrections recorded.</p>}</div>}</div>)}{!editorialQuery.data?.length && <p className="rounded-xl bg-[#f8f9f5] p-5 text-xs text-[#819198]">No journalism submissions yet.</p>}</div>
