        {!isAuthenticated ? <p className="rounded-xl bg-[#f8f9f5] p-5 text-xs text-[#819198]">Sign in to request reporter access.</p> : user?.role === "user" ? <div className="rounded-xl border border-[#e6ebe6] bg-white p-4"><div className="grid gap-2 sm:grid-cols-2"><Input value={reporterOutlet} onChange={e => setReporterOutlet(e.target.value)} placeholder="Outlet / organization" className="text-xs"/><Input value={reporterEvidence} onChange={e => setReporterEvidence(e.target.value)} placeholder="Portfolio or evidence URL" className="text-xs"/></div><Textarea value={reporterBio} onChange={e => setReporterBio(e.target.value)} placeholder="Reporter bio (minimum 20 characters)" className="mt-2 min-h-28 text-xs"/><Button onClick={() => { if (reporterBio.trim().length < 20) return toast.error("Reporter bio must be at least 20 characters"); requestReporterMutation.mutate({ outlet: reporterOutlet.trim() || undefined, bio: reporterBio.trim(), evidence: reporterEvidence.trim() || undefined }); }} disabled={requestReporterMutation.isPending} className="mt-3 h-9 rounded-full bg-[#2b9a8b] px-4 text-xs font-bold">Request reporter status</Button></div> : <p className="rounded-xl bg-[#e0f3ee] p-5 text-xs font-bold text-[#277568]">Your current role is <span className="uppercase">{user?.role}</span>.</p>}
