        {isAuthenticated && <div className="grid gap-4 sm:grid-cols-2"><div className="rounded-xl border border-[#dfe9e4] bg-white p-4"><p className="text-sm font-extrabold text-[#23475d]">Blocked users</p>{blockedUsersQuery.data?.map(person => <div key={person.id} className="mt-2 flex items-center justify-between rounded-lg bg-[#f8f9f5] p-2"><span className="text-xs font-bold text-[#536b75]">{person.name || `User #${person.id}`}</span><button onClick={() => blockMutation.mutate({ userId: person.id })} className="rounded-full bg-white px-2 py-1 text-[9px] font-bold text-[#315f70]">Unblock</button></div>)}{!blockedUsersQuery.data?.length && <p className="mt-2 text-[11px] text-[#819198]">No blocked users.</p>}</div><div className="rounded-xl border border-[#dfe9e4] bg-white p-4"><p className="text-sm font-extrabold text-[#23475d]">Muted users</p>{mutedUsersQuery.data?.map(person => <div key={person.id} className="mt-2 flex items-center justify-between rounded-lg bg-[#f8f9f5] p-2"><span className="text-xs font-bold text-[#536b75]">{person.name || `User #${person.id}`}</span><button onClick={() => muteMutation.mutate({ userId: person.id })} className="rounded-full bg-white px-2 py-1 text-[9px] font-bold text-[#315f70]">Unmute</button></div>)}{!mutedUsersQuery.data?.length && <p className="mt-2 text-[11px] text-[#819198]">No muted users.</p>}</div></div>}
        {user?.role === "admin" && <><div className="rounded-xl border border-[#dfe9e4] bg-white p-4"><div className="flex items-center justify-between"><div className="flex items-center gap-2"><p className="text-sm font-extrabold text-[#23475d]">Admin review queue</p><button onClick={() => { const value = window.prompt(t("Post ID to open a moderation case")); const postId = Number(value); if (Number.isInteger(postId) && postId > 0) createModerationCaseMutation.mutate({ postId, priority: "normal", note: "Manual admin review case" }); }} className="rounded-full border border-[#dfe7e4] bg-white px-2.5 py-1.5 text-[9px] font-bold text-[#315f70]">Open case</button></div><Badge>{adminReviewQueueQuery.data?.reports.length ?? 0} reports · {adminReviewQueueQuery.data?.cases.length ?? 0} cases · {adminReviewQueueQuery.data?.appeals.length ?? 0} appeals</Badge></div>{adminReviewQueueQuery.data?.reports.map(report => <div key={report.id} className="mt-3 rounded-xl bg-[#f8f9f5] p-3"><p className="text-xs font-extrabold">Report #{report.id} · {report.reason}</p><p className="mt-1 text-[11px] text-[#71858c]">Post #{report.postId} {report.title ? `· ${report.title}` : ""}</p><div className="mt-2 flex gap-2"><button onClick={() => reviewReportMutation.mutate({ reportId: report.id, decision: "reviewed" })} className="rounded-full bg-[#2b9a8b] px-3 py-1.5 text-[10px] font-bold text-white">Resolve</button><span className="rounded-full bg-[#eef6f3] px-3 py-1.5 text-[10px] font-bold text-[#47766f]">Case auto-opened</span><button onClick={() => reviewReportMutation.mutate({ reportId: report.id, decision: "dismissed" })} className="rounded-full bg-[#f1f2ed] px-3 py-1.5 text-[10px] font-bold text-[#5f737c]">Dismiss</button></div></div>)}{adminReviewQueueQuery.data?.cases.map(item => <div key={`case-${item.id}`} className="mt-3 rounded-xl bg-[#eef6f3] p-3"><p className="text-xs font-extrabold">Case #{item.id} · {item.priority} · Post #{item.postId}</p><p className="mt-1 text-[11px] text-[#71858c]">{item.title || "Untitled content"}</p><div className="mt-2 flex gap-2"><button onClick={() => reviewModerationCaseMutation.mutate({ caseId: item.id, decision: "resolved", note: "Reviewed by admin" })} className="rounded-full bg-[#2b9a8b] px-3 py-1.5 text-[10px] font-bold text-white">Resolve case</button><button onClick={() => reviewModerationCaseMutation.mutate({ caseId: item.id, decision: "dismissed", note: "No policy violation confirmed" })} className="rounded-full bg-white px-3 py-1.5 text-[10px] font-bold">Dismiss case</button></div></div>)}</div><div className="rounded-xl border border-[#dfe9e4] bg-white p-4"><p className="text-sm font-extrabold text-[#23475d]">Audit trail</p>{auditLogsQuery.data?.slice(0,12).map(log => <div key={log.id} className="mt-2 flex justify-between gap-3 text-[10px] text-[#71858c]"><span>{log.action} · {log.entityType} #{log.entityId}</span><span>{new Date(log.createdAt).toLocaleString()}</span></div>)}</div></>}
